B.bMd=s(["steroid","prednisolone","dexamethasone","hydrocortisone","equivalent dose","conversion"],t.s)
B.ajH=new A.c1("sbp","Systolic BP","mmHg","e.g. 100",!1,!1)
B.ajQ=new A.c1("dbp","Diastolic BP","mmHg","e.g. 60",!1,!1)
B.ajr=new A.c1("age","Age (for expected minimum)","years","e.g. 5",!1,!1)
